INSERT INTO fallacies (name, category, description, wikipedia_url, source, enabled) VALUES
('Falácia da falácia (Fallacy Fallacy - Argumentum ad logicam)', 'Falácias formais', 'presumir que, se um argumento específico de uma conclusão for falacioso, a conclusão automaticamente também é falsa. (por exemplo: ignorar ou dispensar um ponto de vista porque o interlocutor se utilizou de ad hominem.)', 'https://pt.wikipedia.org/wiki/Argumento_ad_logicam', 'wikipedia', true),
('Apelo à probabilidade', 'Falácias formais', 'presumir que algo seja correto/verdadeiro porque provavelmente é (ou poderia ser).', 'https://pt.wikipedia.org/wiki/Apelo_%C3%A0_probabilidade', 'wikipedia', false),
('Falácia da taxa-base', 'Falácias formais', 'ignorar a taxa base em favor da informação individualizadora.', 'https://pt.wikipedia.org/wiki/Fal%C3%A1cia_da_taxa-base', 'wikipedia', false),
('Falácia da conjunção', 'Falácias formais', 'presumir que um resultado que satisfaça várias condições simultaneamente é mais provável do que um resultado que satisfaça apenas uma delas.', 'https://pt.wikipedia.org/wiki/Fal%C3%A1cia_da_conjun%C3%A7%C3%A3o', 'wikipedia', false),
('Falácia da probabilidade condicionada', 'Falácias formais', 'fazer um julgamento de probabilidade com base em probabilidades condicionadas, sem levar em consideração o efeito das probabilidades a priori.', NULL, 'wikipedia', false),
('Falácia do homem mascarado (substituição ilícita de idênticos)', 'Falácias formais', 'substituir um elemento por outro (supostamente) idêntico, distorcendo o argumento. (por exemplo: substituir uma palavra por outra de significado parecido, mas que, dependendo do contexto aplicado, pode levar à uma conclusão falsa.)', 'https://pt.wikipedia.org/wiki/Fal%C3%A1cia_do_homem_mascarado', 'wikipedia', false),
('Non sequitur', 'Falácias formais', 'onde a conclusão não segue logicamente a premissa.', 'https://pt.wikipedia.org/wiki/Non_sequitur', 'wikipedia', false),
('Afirmar uma disjunção', 'Falácias proposicionais', 'concluir que uma disjunção de uma disjunção lógica deve ser falsa porque a outra disjunção é verdadeira.', 'https://pt.wikipedia.org/wiki/Afirmar_uma_disjun%C3%A7%C3%A3o', 'wikipedia', false),
('Afirmação do consequente', 'Falácias proposicionais', 'o antecedente em um condicional indicativo é afirmado como verdadeiro porque o consequente é verdadeiro.', 'https://pt.wikipedia.org/wiki/Afirma%C3%A7%C3%A3o_do_consequente', 'wikipedia', false),
('Negação do antecedente', 'Falácias proposicionais', 'o consequente em um condicional indicativo é afirmado como falso porque o antecedente é falso.', 'https://pt.wikipedia.org/wiki/Nega%C3%A7%C3%A3o_do_antecedente', 'wikipedia', false),
('Falácia existencial', 'Falácias de quantificação', 'um argumento contém duas premissas universais (todos, todas) para chegar a uma conclusão específica (alguns, algumas). (por exemplo: se TODAS as babás tem acne, e TODAS as integrantes do clube de babás são babás, logo ALGUMAS das integrantes do clube tem acne.)', 'https://pt.wikipedia.org/wiki/Fal%C3%A1cia_existencial', 'wikipedia', false),
('Conclusão afirmativa de uma premissa negativa (negativo incorreto)', 'Falácias silogísticas formais', 'um silogismo categórico tem uma conclusão positiva, mas ao menos uma premissa negativa.', NULL, 'wikipedia', false),
('Conclusão negativa das premissas afirmativas (afirmativo incorreto)', 'Falácias silogísticas formais', 'um silogismo categórico tem uma conclusão negativa, mas premissas afirmativas.', 'https://pt.wikipedia.org/wiki/Conclus%C3%A3o_negativa_das_premissas_afirmativas', 'wikipedia', false),
('Falácia de premissas exclusivas', 'Falácias silogísticas formais', 'um silogismo categórico que é inválido porque ambas as premissas são negativas.', 'https://pt.wikipedia.org/wiki/Fal%C3%A1cia_de_premissas_exclusivas', 'wikipedia', false),
('Falácia do escopo modal', 'Falácias silogísticas formais', 'um nível de necessidade injustificado é posto na conclusão.', 'https://pt.wikipedia.org/wiki/Fal%C3%A1cia_modal', 'wikipedia', false),
('Falácia do termo médio não distribuído', 'Falácias silogísticas formais', 'o termo do meio em um silogismo categórico não é distribuído.', 'https://pt.wikipedia.org/wiki/Fal%C3%A1cia_do_termo_m%C3%A9dio_n%C3%A3o_distribu%C3%ADdo', 'wikipedia', false),
('Falácia dos quatro termos', 'Falácias silogísticas formais', 'um silogismo categórico que possui quatro termos.', 'https://pt.wikipedia.org/wiki/Fal%C3%A1cia_dos_quatro_termos', 'wikipedia', false),
('Falácia modal', 'Falácias silogísticas formais', 'confundir necessidade com suficiência.', 'https://pt.wikipedia.org/wiki/Fal%C3%A1cia_modal', 'wikipedia', false),
('Ilícito maior', 'Falácias silogísticas formais', 'um silogismo categórico que é inválido porque seu termo principal não é distribuído na premissa maior, mas na conclusão.', NULL, 'wikipedia', false),
('Ilícito menor', 'Falácias silogísticas formais', 'um silogismo categórico que é inválido porque seu termo menor não é distribuído na premissa menor, mas distribuído na conclusão.', NULL, 'wikipedia', false),
('Argumentum ad temperantiam (equilíbrio falso, meio-termo, apelo à moderação)', 'Falácias informais', 'presumir que um meio-termo entre duas posições está sempre correto.', 'https://pt.wikipedia.org/wiki/Argumentum_ad_temperantiam', 'wikipedia', false),
('Atribuição falsa', 'Falácias informais', 'em suporte de um argumento, apelar para uma fonte irrelevante, não-identificável, indefinida, tendenciosa ou fabricada.', 'https://pt.wikipedia.org/wiki/Atribui%C3%A7%C3%A3o_falsa', 'wikipedia', false),
('Autoridade falsa (autoridade única)', 'Falácias informais', 'usar um especialista de credenciais duvidosas ou usar apenas uma opinião para promover uma ideia. Relacionado à apelo à autoridade.', 'https://pt.wikipedia.org/wiki/Argumentum_ad_verecundiam', 'wikipedia', false),
('Falácia da citação fora de contexto (contextotomia)', 'Falácias informais', 'retirada seletiva de palavras de seu contexto original para distorcer o significado desejado.', 'https://pt.wikipedia.org/wiki/Cita%C3%A7%C3%A3o_fora_de_contexto', 'wikipedia', false),
('Ladeira escorregadia (Slippery Slope)', 'Falácias informais', 'afirmar que uma ação, relativamente pequena, irá inevitavelmente levar a uma corrente de eventos subsequentes e, portanto, não deve ser permitida.', NULL, 'wikipedia', true),
('Contar duplamente', 'Falácias informais', 'contar eventos ou ocorrências mais que uma vez em raciocínios de probabilidade, o que leva a soma de probabilidades de todos os casos exceder a unidade.', NULL, 'wikipedia', false),
('Correlação suprimida', 'Falácias informais', 'uma correlação é redefinida para que as alternativas sejam impossíveis. (por exemplo: "Eu não sou gordo, pois sou mais magro que João.").', NULL, 'wikipedia', false),
('Equívoco (Equivocation)', 'Falácias informais', 'usar um termo com mais de um significado em uma afirmação sem especificar qual o significado atribuído.', 'https://pt.wikipedia.org/wiki/Equ%C3%ADvoco', 'wikipedia', true),
('Definição persuasiva', 'Falácias informais', 'pretensiosamente usar a definição "verdadeira" ou "comumente aceitada" enquanto, na realidade, usa-se uma definição incomum ou alterada.', NULL, 'wikipedia', false),
('Falácia motte-and-bailey', 'Falácias informais', 'conflitar duas posições com propriedades similares, uma modesta e fácil de defender (a "motte") e uma mais controversa (a "bailey"). O argumentador primeiramente estabelece a posição controversa, mas quando desafiado, estabelece que está avançando à posição modesta.', NULL, 'wikipedia', false),
('Meio-termo ambíguo', 'Falácias informais', 'usar um meio-termo com vários significados.', NULL, 'wikipedia', false),
('Retratação da definição', 'Falácias informais', 'mudar o significado de uma palavra quando uma objeção é levantada. Frequentemente usada junto com mudança de critérios (ver abaixo), como quando um argumento é desafiado usando uma definição comum de um termo no argumento, e o argumentador apresenta uma definição diferente do termo e portanto demanda uma evidência diferente para desacreditar do argumento.', NULL, 'wikipedia', false),
('Falácia continuum (falácia da barba, falácia do homem calvo)', 'Falácias informais', 'rejeitar impropriamente um posicionamento por ser impreciso.', 'https://pt.wikipedia.org/wiki/Fal%C3%A1cia_continuum', 'wikipedia', false),
('Falácia de composição', 'Falácias informais', 'assumir que algo verdadeiro de uma parte do conjunto há de ser verdadeiro também pelo conjunto como um todo.', NULL, 'wikipedia', false),
('Falácia de definição', 'Falácias informais', 'definir um termo usado em um argumento de forma enviesada (por exemplo: usar "termos carregados"). A pessoa fazendo o argumento espera que o interlocutor irá aceitar a definição dada, fazendo com que o argumento seja difícil de refutar.', NULL, 'wikipedia', false),
('Falácia de divisão', 'Falácias informais', 'assumir que algo verdadeiro de um conjunto há de ser verdadeiro para todas (ou algumas de) suas partes. (por exemplo: "O ser humano normalmente tem 2 pernas. Logo, todos os seres humanos tem 2 pernas.")', NULL, 'wikipedia', false),
('Apelo à incredulidade (Argument from Incredulity)', 'Falácias informais', 'argumentar que, por algo ser tão incrível ou maravilhoso, ele há de ser superior, divino, alienígena ou uma atividade paranormal.', NULL, 'wikipedia', true),
('Falácia do feedback', 'Falácias informais', 'acreditar na objetividade de uma avaliação usada como base para melhoria, sem verificar se a fonte da avaliação é pertinente.', NULL, 'wikipedia', false),
('Falácia do historiador', 'Falácias informais', 'presumir que pessoas que tomaram decisões no passado tinham informações idênticas as subsequentes que analisaram a decisão. Não deve ser confundido com presentismo, no qual as ideias do presente e perspectivas são anacronicamente projetadas ao passado.', NULL, 'wikipedia', false),
('Falácia ecológica', 'Falácias informais', 'inferir sobre a natureza de uma entidade baseando-se apenas em estatísticas agregadas coletadas pelo grupo que a entidade pertence.', NULL, 'wikipedia', false),
('Falácia etimológica', 'Falácias informais', 'assumir que o significado original ou histórico de uma palavra ou frase é necessariamente similar ao real uso atual.', NULL, 'wikipedia', false),
('Falácia histórica', 'Falácias informais', 'um erro na interpretação na qual alguém lê em um processo, seja como uma causa ou um elemento essencial, que apenas vem como resultado do processo.', NULL, 'wikipedia', false),
('Falácia baconiana', 'Falácias informais', 'usar pedaços de evidências históricas sem ajuda dos métodos específicos, hipóteses, ou teorias em uma tentativa de fabricar uma verdade geral sobre o passado. Compromete historiadores "à busca de um objeto impossível por um método impraticável".', NULL, 'wikipedia', false),
('Falsa dicotomia (False Dilemma)', 'Falácias informais', 'duas afirmações alternativas são dadas como as únicas opções possíveis quando, na realidade, há mais.', 'https://pt.wikipedia.org/wiki/Falsa_dicotomia', 'wikipedia', true),
('Pergunta complexa (plurium interrogationum)', 'Premissa imprópria', 'alguém faz uma pergunta que pressupõe algo que não foi provado ou aceito por todas as pessoas envolvidas. Essa falácia é frequentemente usada de forma retórica para que a questão limite as respostas diretas àquelas que atendem às intenções do questionador.', 'https://pt.wikipedia.org/wiki/Pergunta_complexa', 'wikipedia', false),
('Petição de princípio (Begging the Question - Petitio principii)', 'Premissa imprópria', 'usar a conclusão do argumento para se apoiar em uma premissa.', 'https://pt.wikipedia.org/wiki/Petitio_principii', 'wikipedia', true),
('Rótulo carregado', 'Premissa imprópria', 'embora não seja necessariamente falaciosa, o uso de termos evocativos para apoiar uma conclusão é um tipo de falácia petitio principii. Quando usado de forma falaciosa, as conotações do termo são utilizadas para influenciar o argumento em direção a uma conclusão específica. Por exemplo, um anúncio de alimentos orgânicos que diz "Alimentos orgânicos são alimentos seguros e saudáveis cultivados sem pesticidas, herbicidas ou outros aditivos prejudiciais à saúde". O uso do termo "aditivos não saudáveis" é usado como suporte para a ideia de que o produto é seguro.', NULL, 'wikipedia', false),
('Dicto secundum quid ad dictum simpliciter (Acidente)', 'Generalizações falsas', 'uma exceção de uma generalização é ignorada.', 'https://pt.wikipedia.org/wiki/Dicto_secundum_quid_ad_dictum_simpliciter', 'wikipedia', false),
('Falácia do escocês de verdade (No True Scotsman)', 'Generalizações falsas', 'torna uma generalização verdadeira alterando a generalização para excluir um contra-exemplo.', 'https://pt.wikipedia.org/wiki/Fal%C3%A1cia_do_escoc%C3%AAs_de_verdade', 'wikipedia', true),
('Exceção avassaladora', 'Generalizações falsas', 'uma generalização precisa que vem com qualificações que eliminam tantos casos que o que resta é muito menos impressionante do que a afirmação inicial poderia ter levado a supor.', NULL, 'wikipedia', false),
('Falsa analogia (False Analogy)', 'Generalizações falsas', 'um argumento por analogia em que a analogia é inadequada.', NULL, 'wikipedia', true),
('Generalização precipitada (Hasty Generalization)', 'Generalizações falsas', 'basear uma conclusão ampla em uma amostra pequena ou não representativa.', 'https://pt.wikipedia.org/wiki/Generaliza%C3%A7%C3%A3o_precipitada', 'wikipedia', true),
('Evidência suprimida', 'Generalizações falsas', 'usar casos individuais ou dados que confirmam uma posição específica, enquanto ignora casos relacionados ou dados que podem contradizer essa posição. Um tipo de viés de confirmação.', 'https://pt.wikipedia.org/wiki/Evid%C3%AAncia_suprimida', 'wikipedia', false),
('Falácia post hoc (Post Hoc Fallacy - Post hoc ergo propter hoc)', 'Causa questionável', 'X aconteceu, depois Y aconteceu; portanto, X causou Y.', 'https://pt.wikipedia.org/wiki/Post_hoc_ergo_propter_hoc', 'wikipedia', true),
('Inversão de causa e efeito (causa reversa)', 'Causa questionável', 'causa e efeito são invertidos. Diz-se que a causa é o efeito e vice-versa.', 'https://pt.wikipedia.org/wiki/Invers%C3%A3o_de_causa_e_efeito', 'wikipedia', false),
('Causa complexa', 'Causa questionável', 'presume-se que existe uma causa simples para um resultado quando, na realidade, ele pode ter sido causado por um número de causas apenas conjuntamente suficientes.', 'https://pt.wikipedia.org/wiki/Causa_complexa', 'wikipedia', false),
('Falácia do apostador', 'Causa questionável', 'a crença incorreta de que eventos separados e independentes podem afetar a probabilidade de outro evento aleatório. Se uma moeda justa der cara 10 vezes consecutivas, a crença de que é "devido ao número de vezes que ela anteriormente deu coroa" é incorreta.', 'https://pt.wikipedia.org/wiki/Fal%C3%A1cia_do_apostador', 'wikipedia', false),
('Apelo à ignorância (Argument from Ignorance - Ad ignorantiam)', 'Falácias de relevância', 'assumir que uma afirmação é verdadeira porque não pode ser provada falsa.', 'https://pt.wikipedia.org/wiki/Argumentum_ad_ignorantiam', 'wikipedia', true),
('Apelo à incredulidade (apelo ao senso comum)', 'Falácias de relevância', 'assumir que uma afirmação é falsa por não conceber ela sendo verdadeira. "Não consigo imaginar isto como verdade; logo, isto há de ser falso."', NULL, 'wikipedia', false),
('Argumentum ad lapidem', 'Falácias de relevância', 'rejeitar uma afirmação considerando-a como absurda sem demonstrar provas sobre seu absurdo.', 'https://pt.wikipedia.org/wiki/Argumentum_ad_lapidem', 'wikipedia', false),
('Argumentum ad nauseam (Apelo à repetição, argumentum ad infinitum)', 'Falácias de relevância', 'repetir um argumento até que todos se cansem ou percam a paciência de discuti-lo; algumas vezes confundido com proof by assertion.', 'https://pt.wikipedia.org/wiki/Argumentum_ad_nauseam', 'wikipedia', false),
('Argumentum ex silentio', 'Falácias de relevância', 'assumir que uma premissa é verdadeira baseada na ausência de evidência falada ou escrita de uma fonte confiável, ou vice versa.', 'https://pt.wikipedia.org/wiki/Argumentum_ex_silentio', 'wikipedia', false),
('Ignoratio elenchi', 'Falácias de relevância', 'um argumento que por si só pode ser válido, mas não se relaciona ao tema em questão.', 'https://pt.wikipedia.org/wiki/Ignoratio_elenchi', 'wikipedia', false),
('Pista Falsa (Red Herring)', 'Falácias red herring', 'introduzir um segundo argumento em resposta ao primeiro que é irrelevante e rouba atenção do tópico primário. (ex: dizer “Se você quer reclamar da louça que eu deixo na pia, que tal as roupas sujas que você deixa no banheiro?”)', 'https://pt.wikipedia.org/wiki/Pista_falsa', 'wikipedia', true),
('Ataque pessoal (Personal Attack - Ad hominem)', 'Falácias red herring', 'atacar o argumentador ao invés do argumento em si. (Note que "ad hominem" pode também referir-se a estratégia dialética de argumentar baseando-se nos compromissos do oponente. Esse tipo de ad hominem não é uma falácia.)', 'https://pt.wikipedia.org/wiki/Ad_hominem', 'wikipedia', true),
('Ad hominem circumstantial', 'Falácias red herring', 'assumir que uma conclusão é falsa por causa de "segundas intenções" por trás da conclusão (ex: benefício pessoal).', 'https://pt.wikipedia.org/wiki/Ad_hominem', 'wikipedia', false),
('Envenenando o poço (Poisoning the Well)', 'Falácias red herring', 'um subtipo de ad hominem que apresenta informações diversas sobre uma pessoa-alvo com a intenção de desmoralizar ou causar descrédito a tudo que a pessoa-alvo diz.', 'https://pt.wikipedia.org/wiki/Envenenando_o_po%C3%A7o', 'wikipedia', true),
('Apelo à autoridade (Appeal to Authority - Argumentum ad verecundiam)', 'Falácias red herring', 'uma asserção é dita como verdadeira por causa da posição ou autoridade da pessoa que a asserte.', 'https://pt.wikipedia.org/wiki/Argumentum_ad_verecundiam', 'wikipedia', true),
('Apelo às consequências (Appeal to Consequences - Ad consequentiam)', 'Falácias red herring', 'a conclusão é baseada por uma premissa que afirma consequências (tipicamente de curto prazo) positivas ou negativas de alguma ação numa tentativa de distrair da discussão inicial e dos princípios.', 'https://pt.wikipedia.org/wiki/Argumentum_ad_consequentiam', 'wikipedia', true),
('Apelo à emoção (Appeal to Emotion)', 'Falácias red herring', 'manipular as emoções do interlocutor ao invés de usar um raciocínio válido para chegar num acordo em comum.', 'https://pt.wikipedia.org/wiki/Apelo_%C3%A0_emo%C3%A7%C3%A3o', 'wikipedia', true),
('Apelo ao medo', 'Falácias red herring', 'gerar estresse, ansiedade, cinismo, ou preconceito com o oponente em uma discussão.', 'https://pt.wikipedia.org/wiki/Apelo_ao_medo', 'wikipedia', false),
('Apelo à elogios', 'Falácias red herring', 'elogiar excessivamente ou desonestamente para chegar num acordo em comum.', NULL, 'wikipedia', false),
('Argumentum ad misericordiam (Apelo à misericórdia)', 'Falácias red herring', 'gerar sentimentos de simpatia ou misericórdia no interlocutor para chegar num acordo.', 'https://pt.wikipedia.org/wiki/Argumentum_ad_misericordiam', 'wikipedia', false),
('Apelo ao ridículo (reductio ad ridiculum, reductio ad absurdum)', 'Falácias red herring', 'debochar ou dizer que a posição do oponente é cômica para desviar dos méritos do argumento do oponente. (Note que "reductio ad absurdum" também pode se referir a forma clássica de argumentação que estabelece uma premissa por mostrar que o cenário oposto resultaria em algo absurdo ou contraditório. Esse tipo de ad absurdum não é uma falácia.)', 'https://pt.wikipedia.org/wiki/Apelo_ao_rid%C3%ADculo', 'wikipedia', false),
('Apelo à hostilidade', 'Falácias red herring', 'gerar acidez ou hostilidade no interlocutor direcionado ao oponente em uma discussão.', NULL, 'wikipedia', false),
('Pooh-pooh', 'Falácias red herring', 'dizer que um argumento do oponente não merece ser levado em consideração.', NULL, 'wikipedia', false),
('Wishful thinking', 'Falácias red herring', 'argumentar pelo intuito do interlocutor de acordo com o que pode ser prazeroso de imaginar ao invés de estar de acordo com uma evidência ou razão.', 'https://pt.wikipedia.org/wiki/Wishful_thinking', 'wikipedia', false),
('Apelo à natureza', 'Falácias red herring', 'o julgamento é baseado somente no fato do sujeito do julgamento ser ''natural'' ou ''não-natural''. (Algumas vezes também chamada de "falácia natural", mas não deve ser confundida com as outras falácias por esse nome.)?', 'https://pt.wikipedia.org/wiki/Apelo_%C3%A0_natureza', 'wikipedia', false),
('Argumentum ad novitatem', 'Falácias red herring', 'uma proposta é dita como superior ou melhor somente por ser nova ou moderna.', 'https://pt.wikipedia.org/wiki/Argumentum_ad_novitatem', 'wikipedia', false),
('Argumentum ad lazarum', 'Falácias red herring', 'apoiar uma conclusão porque o argumentador é pobre (ou refutar porque o argumentador é rico).', 'https://pt.wikipedia.org/wiki/Argumentum_ad_lazarum', 'wikipedia', false),
('Argumentum ad crumenam', 'Falácias red herring', 'apoiar uma conclusão porque o argumentador é rico (ou refutar porque o argumentador é pobre).', 'https://pt.wikipedia.org/wiki/Argumentum_ad_crumenam', 'wikipedia', false),
('Apelo à tradição (Appeal to Tradition - Ad antiquitatem)', 'Falácias red herring', 'uma conclusão é apoiada somente porque foi por muito tempo dita como verdadeira.', 'https://pt.wikipedia.org/wiki/Argumentum_ad_antiquitatem', 'wikipedia', true),
('Argumentum ad baculum', 'Falácias red herring', 'um argumento feio por coerção or ameaças de força para apoiar uma oposição.', 'https://pt.wikipedia.org/wiki/Argumentum_ad_baculum', 'wikipedia', false),
('Apelo à maioria (Appeal to the Majority - Argumentum ad populum)', 'Falácias red herring', 'uma proposição é dita como verdadeira ou boa apenas porque a maioria das pessoas acreditam que ela é.', 'https://pt.wikipedia.org/wiki/Argumentum_ad_populum', 'wikipedia', true),
('Dois errados fazem um certo', 'Falácias red herring', 'assumir que, se um erro é cometido, outro erro irá repará-lo.', NULL, 'wikipedia', false),
('Esnobismo cronológico', 'Falácias red herring', 'uma tese é entendida como incorreta por ter sido comumente usada quando outra coisa, sendo ela falsa, também era comumente usada.', 'https://pt.wikipedia.org/wiki/Esnobismo_cronol%C3%B3gico', 'wikipedia', false),
('Falácia de associação (culpa por associação, honra por associação)', 'Falácias red herring', 'argumentar que por duas coisas compartilharem (ou serem implícitas de compartilharem) alguma propriedade, elas são a mesma coisa.', NULL, 'wikipedia', false),
('Nut-picking (Escolher a dedo)', 'Falácias red herring', 'focar nos detalhes triviais de um argumento, ao invés do ponto principal da argumentação.', NULL, 'wikipedia', false),
('Falácia da privação relativa', 'Falácias red herring', 'rejeitar um argumento ou reclamação por considerar outros problemas mais importantes. First World problems são uma subseção desta falácia.', NULL, 'wikipedia', false),
('Falácia do atirador de elite do Texas', 'Falácias red herring', 'impropriamente afirmar um caso para explicar um grupo de dados.', 'https://pt.wikipedia.org/wiki/Fal%C3%A1cia_do_atirador_de_elite_do_Texas', 'wikipedia', false),
('Apelo à hipocrisia (Appeal to Hypocrisy - Tu quoque)', 'Falácias red herring', 'dizer que uma posição é falsa, errada, ou deveria ser rejeitada porque o oponente falha em agir consistente de acordo com ela.', 'https://pt.wikipedia.org/wiki/Tu_quoque', 'wikipedia', true),
('Falácia do espantalho (Straw Man)', 'Falácias red herring', 'representar erroneamente um argumento do oponente por meio de aumentar ou diminuir o âmbito da premissa e refutar a versão mais fraca.', 'https://pt.wikipedia.org/wiki/Fal%C3%A1cia_do_espantalho', 'wikipedia', true),
('Falácia genética', 'Falácias red herring', 'uma conclusão é sugerida baseada somente na origem de algo ou alguém, ao invés do significado ou contexto atual.', 'https://pt.wikipedia.org/wiki/Fal%C3%A1cia_gen%C3%A9tica', 'wikipedia', false),
('Falácia moralista', 'Falácias red herring', 'inferir conclusão factuais de premissas de nivelação, em violação da distinção de fato-valor (por exemplo: fazer afirmações sobre o que algo é, baseando-se em afirmações sobre o que algo deve (moralmente) ser.) Essa é a falácia oposta a falácia naturalista.?', 'https://pt.wikipedia.org/wiki/Fal%C3%A1cia_moralista', 'wikipedia', false),
('Falácia naturalista (às vezes confundida com apelo à natureza)', 'Falácias red herring', 'inferir conclusões de nivelação por premissas puramente factuais em detrimento da distinção de fato-valor.', NULL, 'wikipedia', false),
('Lei de Hume', 'Falácias red herring', 'afirmações sobre o que deve ser com base em afirmações sobre o que é.', 'https://pt.wikipedia.org/wiki/Lei_de_Hume', 'wikipedia', false),
('Ipse dixit (falácia de asserção nua)', 'Falácias red herring', 'uma afirmação que é apresentada como verdadeira sem apoio, como sendo verdadeira por si só, ou como dogmaticamente verdadeira. Essa falácia se baseia na perícia implícita do orador ou em uma verdade não-dita.', 'https://pt.wikipedia.org/wiki/Ipse_dixit', 'wikipedia', false)
